\begin{defn}\label{defn:normal-modal-logic}
A modal logic~$\Log L$ is \emph{normal} iff 
\begin{enumerate}
\item it contains both
\begin{align}
\tag{K} \Box(p \lif q) & \lif (\Box p \lif \Box q) \\
\tag{Dual} \Diamond p & \liff \lnot \Box \lnot p
\end{align}
\item and it is closed under necessitation, i.e., whenever $!A \in
  \Log L$, then also $\Box !A \in \Log L$.
\end{enumerate}
\end{defn}

\begin{thm}
\ollabel{thm:church-rosser}
Let $M$, $N_1$, and $N_2$ be terms, such that $M \red N_1$ and $M \red
N_2$. Then there is a term $P$ such that $N_1 \red P$ and $N_2 \red P$.
\end{thm}

\begin{defn}
\ollabel{defn:reduct}
Suppose $\Lang L \subseteq \Lang L'$, $\Struct M$ is an
$\Lang L$-!!{structure} and $\Struct M'$ is an $\Lang L'$-!!{structure}.
$\Struct M$ is the \emph{reduct} of $\Struct M'$ to $\Lang L$, and
$\Struct M'$ is an \emph{expansion} of $\Struct M$ to $\Lang L'$ iff
\begin{enumerate}
\item $\Domain{M} = \Domain{M'}$
\item For every !!{constant}~$c \in \Lang L$, $\Assign{c}{M} =
  \Assign{c}{M'}$.
\item For every !!{function}~$f \in \Lang L$, $\Assign{f}{M} =
  \Assign{f}{M'}$.
\item For every !!{predicate}~$P \in \Lang L$, $\Assign{P}{M} =
  \Assign{P}{M'}$.
\end{enumerate}
\end{defn}

